script:
res = {}
res["root"] = repo.list(".")
res["src"] = repo.list("src")
for hit in repo.search("memory_budget", glob = "**/*"):
    res.setdefault("hits", []).append("%s:%d %s" % (hit.path, hit.line, hit.text))
for p in ["Cargo.toml", "src/lib.rs", "src/cache.rs"]:
    c = repo.read(p, missing_ok = True)
    res[p] = c if c == None or len(c) < 2000 else c[:2000]
return res
